// RoomInformation -> rooms. An unreadable or empty tab must never switch every room off: in that case the
// last good list is kept and the problem reported.
const c = $('Each Client').first().json;
const items = $input.all().map((i) => i.json || {});
const failed = items.find((j) => j.error);
const rows = items.filter((j) => !j.error && Object.keys(j).length);
const KNOWN = ['row_number', 'RoomNumber', 'RoomType', 'Persons', 'Description'];
const problems = [], rooms = [], seen = new Set();
if (failed) problems.push('could not read the RoomInformation tab: ' + String((failed.error && failed.error.message) || failed.error).slice(0, 160));
for (const r of rows) {
  const num = String(r.RoomNumber ?? '').trim();
  if (!num) { if (Object.entries(r).some(([k, v]) => k !== 'row_number' && String(v ?? '').trim())) problems.push('row ' + r.row_number + ' has no RoomNumber'); continue; }
  if (seen.has(num)) { problems.push('room ' + num + ' is listed twice (row ' + r.row_number + ')'); continue; }
  seen.add(num);
  let persons = null;
  if (String(r.Persons ?? '').trim() !== '') { persons = parseInt(String(r.Persons), 10); if (!(persons > 0)) { problems.push('room ' + num + ': Persons must be a number above 0'); persons = null; } }
  const extra = {};
  for (const [k, v] of Object.entries(r)) if (!KNOWN.includes(k) && String(v ?? '').trim() !== '') extra[k] = v;
  rooms.push({ room_number: num, room_type: String(r.RoomType ?? '').trim() || null, persons, description: String(r.Description ?? '').trim() || null, extra, sheet_row: r.row_number });
}
if (!failed && !rooms.length) problems.push('the RoomInformation tab has no rooms - kept the previous room list');
return [{ json: Object.assign({}, c, { apply: !failed && rooms.length > 0, rooms: JSON.stringify(rooms), roomCount: rooms.length, problems: problems.join('; ') }) }];

// The read-only copy of the reservations for the owner. Rewritten only when something changed.
const c = $('Check Rooms').first().json;
const items = $input.all().map((i) => i.json || {});
const failed = items.find((j) => j.error);
const rows = items.filter((j) => !j.error && j.Ticket !== undefined);
const header = ['Ticket', 'Booking no.', 'Status', 'Guest', 'Phone', 'Email', 'Room', 'Guests', 'Check-in', 'Check-out', 'Channel', 'Booked at', 'Cancelled at', 'Note'];
const body = rows.map((r) => header.map((h) => String(r[h] ?? '')));
let h = 2166136261; const s = JSON.stringify(body);
for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619) >>> 0; }
const hash = 'fnv1a:' + h.toString(16) + ':' + body.length;
const note = ['Read-only copy of your reservations from Receply. Edits here are overwritten - to change a booking, reply in Chatwoot or ask the operator. Updated ' + new Date().toISOString().slice(0, 16).replace('T', ' ') + ' UTC.'];
return [{ json: Object.assign({}, c, { changed: !failed && hash !== c.prev_hash, hash, rowCount: body.length,
  readError: failed ? String((failed.error && failed.error.message) || failed.error).slice(0, 160) : '',
  values: JSON.stringify([note, header].concat(body)) }) }];

const m = $('Build Mirror').first().json;
let problem = m.readError ? 'could not read the reservations: ' + m.readError : '', hash = m.prev_hash;
if (m.changed) {
  const w = $('Write Tab').isExecuted ? $('Write Tab').first().json : null;
  if (w && !w.error && w.updatedRange) hash = m.hash;
  else problem = 'could not update the "Reservations (Receply)" tab: ' + String((w && w.error && (w.error.message || w.error)) || 'no response').slice(0, 160);
}
return [{ json: Object.assign({}, m, { problems: [m.problems, problem].filter(Boolean).join('; '), mirror_hash: hash, values: undefined }) }];
